window.Seasons=(()=>{
 let scoped=null,records=[],historyError='',busy=false;
 const copy=s=>JSON.parse(JSON.stringify(s)),key=()=> (window.Cloud?.storageKey()||KEY)+'-seasons';
 function scope(){const k=key();if(k===scoped)return;scoped=k;historyError='';try{const raw=JSON.parse(localStorage.getItem(k)||'[]');records=Array.isArray(raw)?raw.filter(validRecord):[]}catch{records=[]}seasonView=null;}
 function validRecord(r){return !!r&&typeof r.season_id==='string'&&/^[a-zA-Z0-9-]{1,100}$/.test(r.season_id)&&Number.isSafeInteger(r.season_number)&&r.season_number>0&&['completed','cancelled'].includes(r.status)&&(!r.snapshot||V.validState(r.snapshot)&&r.snapshot.seasonId===r.season_id&&r.snapshot.seasonNumber===r.season_number&&(r.status!=='completed'||V.complete(r.snapshot)))}
 function persist(){try{const recent=records.filter(r=>r.snapshot&&r.synced).sort((a,b)=>b.season_number-a.season_number).slice(0,5).map(r=>r.season_id);localStorage.setItem(scoped,JSON.stringify(records.map(r=>r.synced&&!recent.includes(r.season_id)?{...r,snapshot:undefined}:r)));return true;}catch{historyError='Bộ nhớ thiết bị đã đầy. Hãy xuất tiến độ và đồng bộ online trước khi tạo thêm mùa.';toast(historyError);return false}}
 function medals(s){return V.podium(s)}
 function played(s){return s.rounds.flat().filter(m=>m.sets).length+(s.playin||[]).filter(m=>m.sets).length+Object.values(s.bracket||{}).filter(Array.isArray).flat().filter(m=>m.sets).length}
 function progress(s){if(V.complete(s))return `Đã hoàn tất · ${played(s)}/${V.totalMatches(s)} trận`;if(!V.started(s))return 'Chưa có trận đấu nào';if(s.bracket)return `Playoff · ${played(s)}/${V.totalMatches(s)} trận toàn giải · ${V.formatName(s)}`;if(s.playin)return `Play-in · ${s.playin.filter(m=>m.sets).length}/4 trận`;return `League · ${s.rounds.flat().filter(m=>m.sets).length}/496 trận · ${s.rounds.filter(r=>r.every(m=>m.sets)).length}/31 vòng`;}
 function archive(s,status){scope();V.ensureSeason(s);if(records.some(r=>r.season_id===s.seasonId))return persist();records.push({season_id:s.seasonId,season_number:s.seasonNumber,status,created_at:s.seasonCreatedAt,ended_at:new Date().toISOString(),podium:medals(s),played:played(s),snapshot:copy(s),synced:false});return persist()}
 function capture(s){scope();V.ensureSeason(s);if(V.complete(s))archive(s,'completed')}
 function pendingFor(s){scope();return records.filter(r=>!r.synced&&r.snapshot&&(r.season_id!==s.seasonId||r.status==='completed'&&V.complete(s))).slice(0,10).map(copy)}
 function ack(batch,expectedScope){if(key()!==expectedScope)return;scope();const ids=new Set(batch.map(r=>r.season_id));records.forEach(r=>{if(ids.has(r.season_id))r.synced=true});persist()}
 function mergeRemote(list,expectedScope){if(key()!==expectedScope)return;scope();historyError='';for(const row of list){if(!validRecord(row))continue;const i=records.findIndex(r=>r.season_id===row.season_id);if(i<0)records.push({...row,synced:true});else if(records[i].synced)records[i]={...row,snapshot:records[i].snapshot,synced:true};}persist();if(['home','history'].includes(tab))window.render()}
 function adopt(list){scope();for(const row of list||[])if(validRecord(row)&&row.snapshot&&!records.some(r=>r.season_id===row.season_id))records.push({...copy(row),synced:false});persist()}
 function historyFailed(expectedScope){if(key()!==expectedScope)return;scope();historyError='Chưa tải được lịch sử online. Các mùa trên thiết bị và mùa đang chơi vẫn được giữ.';if(['home','history'].includes(tab))window.render()}
 function restoreRecords(list){scope();if(!Array.isArray(list)||!list.every(validRecord))return false;records=copy(list);return persist()}
 function acceptRemote(){scope();records=records.filter(r=>r.synced);persist()}
 function canCustomize(){return !V.started(state)&&!seasonView&&!busy}
 function editable(){return !seasonView&&!V.complete(state)&&!busy}
 function customize(){if(busy)return;if(seasonView){seasonView=null;tab='home'}if(!V.started(state)){Settings.discard();navigate('settings');return}if(V.complete(state)){createNext('completed',true);return}showDecision(true)}
 function showDecision(customizing){const box=$('seasonDecision');$('seasonDecisionContent').innerHTML=`<p>Mùa ${state.seasonNumber} đang diễn ra: ${progress(state)}.</p><p class="sub">Chỉ có thể chỉnh đội và thể thức khi mùa mới chưa có trận đấu. Chọn cách xử lý mùa hiện tại:</p><div class="season-choices"><button class="primary" onclick="Seasons.resolve('finish',${customizing})">Mô phỏng hết mùa hiện tại & tạo mùa mới</button><button onclick="Seasons.resolve('cancel',${customizing})">Hủy tiến trình hiện tại & tạo mùa mới</button><button onclick="document.getElementById('seasonDecision').close()">Giữ lại và tiếp tục chơi</button></div><p class="sub">Mùa được mô phỏng sẽ lưu đầy đủ kết quả. Mùa bị hủy được ghi rõ trong lịch sử, không có nhà vô địch.</p>`;if(!box.open)box.showModal()}
 async function resolve(choice,customizing=true){if(busy||!V.started(state)||V.complete(state)||!['finish','cancel'].includes(choice))return;busy=true;$('seasonDecision').close();try{window.Cloud?.backupCurrent();if(choice==='finish')V.finishAll(state);busy=false;createNext(choice==='finish'?'completed':'cancelled',customizing)}finally{busy=false}}
 function createNext(status,customizing){scope();V.ensureSeason(state);if(!archive(state,status))return;const n=Math.max(state.seasonNumber,...records.map(r=>r.season_number))+1,roster=V.ids(state);state=V.fresh(roster,state.playoffFormat||'single');state.seasonNumber=n;seasonView=null;Settings.discard();round=0;tab=customizing?'settings':'league';save();window.render();toast(`Mùa ${n} đã sẵn sàng!`)}
 function requestNew(){if(!V.started(state)){customize();return}if(V.complete(state))createNext('completed',false);else showDecision(false)}
 function start(){if(busy)return;seasonView=null;if(V.complete(state)){createNext('completed',false);return}round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets)));navigate(V.leagueDone(state)?'playoff':'league')}
 function replaceRoster(selected,playoffFormat=state.playoffFormat||'single'){if(!['single','double'].includes(playoffFormat))return false;if(!canCustomize())return false;const meta={seasonId:state.seasonId,seasonNumber:state.seasonNumber,seasonCreatedAt:state.seasonCreatedAt};state={...V.fresh(selected,playoffFormat),...meta};Settings.discard();round=0;tab='home';save();window.render();toast('Đã cập nhật thể thức và đội cho mùa chưa bắt đầu.');return true}
 function all(){scope();V.ensureSeason(state);const active={season_id:state.seasonId,season_number:state.seasonNumber,status:V.complete(state)?'completed':V.started(state)?'active':'ready',created_at:state.seasonCreatedAt,podium:medals(state),played:played(state),snapshot:state,current:true};return [...records.filter(r=>r.season_id!==active.season_id),active].sort((a,b)=>a.season_number-b.season_number)}
 function tiles(){const list=all();return `<div class="season-grid">${list.map(r=>{const done=r.status==='completed',ongoing=r.current&&!done,label=done?'Đã hoàn tất':r.status==='cancelled'?'Đã hủy':r.status==='active'?'Đang diễn ra':'Chưa bắt đầu';return `<article class="panel season-card ${r.current?'current-season':''}"><div class="season-card-top"><span class="eyebrow">SEASON ${String(r.season_number).padStart(2,'0')}</span><span class="badge ${done?'gold':''}">${label}</span></div><h3>Mùa ${r.season_number}</h3>${r.snapshot?`<p class="season-format-label">${V.formatName(r.snapshot)}</p>`:''}${done?`<div class="season-medals">${(r.podium||[]).map((id,i)=>`<div><span>${['🥇','🥈','🥉'][i]}</span>${team(id)}</div>`).join('')}</div>`:`<p class="sub">${r.snapshot?progress(r.snapshot):`${r.played||0} trận đã đấu`}</p><div class="progress"><i style="width:${(r.played||0)/(r.snapshot?V.totalMatches(r.snapshot):531)*100}%"></i></div>`}<div class="actions">${ongoing?`<button class="primary" onclick="Seasons.start()">${V.started(state)?'Tiếp tục giải đấu':'Bắt đầu giải đấu'}</button>`:`<button onclick="Seasons.view('${r.season_id}')">${done?'Xem kết quả mùa giải':'Xem tiến trình đã hủy'} →</button>`}</div></article>`}).join('')}</div>`}
 function home(){scope();$('content').innerHTML=`<div class="section-head"><div><div class="eyebrow">YOUR VOLLEYBALL JOURNEY</div><h2 style="margin-top:8px">Các mùa giải của bạn</h2><p class="sub">Mỗi mùa là một hành trình. Kết quả được giữ lại để bạn xem bất cứ lúc nào.</p></div><button onclick="navigate('history')">Lịch sử giải đấu ↗</button></div>${historyError?`<div class="notice">${historyError}</div>`:''}${tiles()}`}
 function history(){scope();$('content').innerHTML=`<div class="section-head"><div><h2>Lịch sử giải đấu</h2><p class="sub">Mùa đang chơi có thể tiếp tục; các mùa đã kết thúc chỉ xem kết quả.</p></div><button onclick="navigate('home')">← Trang chủ</button></div>${tiles()}`}
 async function view(id){scope();if(id===state.seasonId&&!V.complete(state)){start();return}const scopeKey=key(),row=all().find(r=>r.season_id===id);if(!row)return;let snap=row.snapshot;if(!snap){try{snap=await window.Cloud?.fetchSeason(id)}catch{}if(scopeKey!==key())return;if(!snap||!V.validState(snap)){toast('Cần kết nối mạng để tải kết quả mùa này.');return}const found=records.find(r=>r.season_id===id);if(found)found.snapshot=copy(snap);persist()}seasonView={...row,snapshot:copy(snap)};tab='season-results';window.render()}
 function resultHeader(){const r=seasonView||{season_number:state.seasonNumber,status:'completed',snapshot:state},s=r.snapshot;return `<div class="season-result-heading"><button onclick="navigate('history')">← Lịch sử mùa giải</button><div><span class="badge">${r.status==='cancelled'?'ĐÃ HỦY · CHỈ XEM':'ĐÃ HOÀN TẤT · CHỈ XEM'}</span><h2>Mùa ${r.season_number}</h2><p class="sub">${V.formatName(s)}</p></div></div>${V.complete(s)?`<div class="podium-grid">${medals(s).map((id,i)=>`<div class="panel medal-card place-${i+1}"><span>${['🥇','🥈','🥉'][i]}</span><small>${['VÔ ĐỊCH','Á QUÂN','HẠNG BA'][i]}</small><h3>${team(id)}</h3></div>`).join('')}</div>`:`<div class="notice">Mùa này đã bị hủy ở tiến trình: ${progress(s)}. Không xác định top 3.</div>`}`}
 function results(){const header=resultHeader();renderPlayoff();$('content').innerHTML=header+(!V.leagueDone(displayState())?'<div class="notice">Chưa hoàn tất league nên chưa có nhánh playoff.</div>':$('content').innerHTML);const saved=$('content').innerHTML;renderTable();$('content').innerHTML=saved+`<div style="height:32px"></div>`+$('content').innerHTML;}
 function localRecords(){scope();return copy(records)}
 async function exportAll(){const active=copy(state),scopeKey=key(),list=localRecords();for(const row of list){if(!row.snapshot)row.snapshot=await window.Cloud?.fetchSeason(row.season_id);if(!row.snapshot)throw Error('Cần kết nối mạng để xuất toàn bộ lịch sử.')}if(scopeKey!==key())throw Error('Tài khoản đã thay đổi.');return{format:'volleyworld-seasons',version:1,active,history:list}}
 function importAll(bundle){if(bundle?.format!=='volleyworld-seasons'||!V.validState(bundle.active)||!Array.isArray(bundle.history)||!bundle.history.every(r=>validRecord(r)&&r.snapshot))throw Error('File lịch sử không hợp lệ.');scope();records=bundle.history.map(r=>({...copy(r),synced:false}));persist();return bundle.active}
 return{restoreRecords,adopt,historyFailed,capture,pendingFor,ack,mergeRemote,acceptRemote,canCustomize,editable,customize,resolve,requestNew,start,replaceRoster,home,history,view,results,localRecords,exportAll,importAll,progress};
})();
